-- Taro: domain-specific content per arm (TipTap JSON). Idempotent by slug.
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing owns how the business is found and grown: acquisition, attribution, campaigns, and lifecycle. The hard part is trustworthy attribution — getting one honest story of which spend produced which outcome."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Channels and spend (paid, organic, referral) with cost normalized across platforms"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attribution models and the conformed definition of an acquisition"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Campaign performance and creative/offer experiments"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lifecycle and CRM: onboarding, engagement, winback"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: a defensible attribution model and a CAC that reconciles with Finance.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'marketing';
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sales covers pipeline, forecasting, and the marketplace/tutoring revenue motion. The recurring failure is several definitions of a booking; the arm exists to make one."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pipeline stages, conversion, and velocity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings and marketplace GMV at a single agreed grain"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Forecasting and quota attainment"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rep and territory performance"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: one bookings definition every downstream report inherits.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'sales';
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Customer experience is support, success, retention, and satisfaction — the read on whether the product keeps its promise after the sale."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Support volume, resolution time, and backlog from Zendesk"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CSAT, NPS, and satisfaction trends"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention, churn, and the leading signals of both"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Success motions tied to account health"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: connect support and satisfaction to product usage and churn.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'cx';
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finance is the source of truth for money: revenue, billing, margin, and the numbers the business is run and reported on. Everything here must reconcile to the billing system."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MRR/ARR, expansion, and contraction"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Subscriptions, billing, trials, and dunning from RevenueCat"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gross margin and cost of revenue (including the platform bill)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The revenue source of truth other arms defer to"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: revenue that ties out to billing to the dollar.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'finance';
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Operations covers rostering, schools and districts, capacity, and reliability — the machinery that delivers the product day to day. Identity is the keystone: clean roster and account identity makes every other arm trustworthy."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rostering and SSO (Clever / ClassLink) identity resolution"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"School and district provisioning and adoption"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity, utilization, and operational efficiency"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reliability and the operational SLAs"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: one resolved identity for school, district, and account.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'ops';
update domains set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Platform is the conformed core and shared infrastructure every other arm depends on. It owns the canonical entities so the spokes share numbers instead of recomputing them."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conformed dimensions and facts (the canonical core)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The semantic layer and shared metric definitions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shared staging, the event stream, and the application database"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lineage, testing, and data quality infrastructure"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Priority: a canonical core nothing downstream is allowed to bypass.","marks":[{"type":"italic"}]}]}]}'::jsonb where slug = 'platform';
